1	package net.officefloor.hq.app.invoices;
2	
3	import java.math.BigDecimal;
4	import java.time.LocalDate;
5	import java.util.List;
6	import net.officefloor.hq.app.Audit;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.jdbc.core.RowMapper;
9	import org.springframework.stereotype.Service;
10	import org.springframework.transaction.annotation.Transactional;
11	
12	/**
13	 * Business logic for invoices. Invoices are always viewed in the context of their project, so the
14	 * list is scoped by project id. The derived total the UI shows is computed by the front-end from the
15	 * returned rows; this service just surfaces the project's invoices in a stable order. Marking an
16	 * invoice paid flips its status and records an audit entry so the action can be checked later.
17	 */
18	@Service
19	public class InvoiceService {
20	
21	    private final InvoiceRepository repository;
22	    private final LineItemRepository lineItemRepository;
23	    private final JdbcTemplate jdbc;
24	    private final Audit audit;
25	
26	    public InvoiceService(InvoiceRepository repository, LineItemRepository lineItemRepository,
27	            JdbcTemplate jdbc, Audit audit) {
28	        this.repository = repository;
29	        this.lineItemRepository = lineItemRepository;
30	        this.jdbc = jdbc;
31	        this.audit = audit;
32	    }
33	
34	    /** Every invoice across all projects; narrowed to a single lifecycle stage when {@code status} is given. */
35	    @Transactional(readOnly = true)
36	    public List<AllInvoiceView> listAll(String status) {
37	        RowMapper<AllInvoiceView> mapper = (rs, i) -> new AllInvoiceView(rs.getLong("id"),
38	                rs.getString("project_name"), rs.getBigDecimal("amount"), rs.getString("status"));
39	        String base = "SELECT i.id, i.amount, i.status, p.name AS project_name "
40	                + "FROM invoices i JOIN projects p ON i.project_id = p.id ";
41	        if (status == null || status.isBlank()) {
42	            return jdbc.query(base + "ORDER BY i.id ASC", mapper);
43	        }
44	        return jdbc.query(base + "WHERE i.status = ? ORDER BY i.id ASC", mapper, status.trim());
45	    }
46	
47	    @Transactional(readOnly = true)
48	    public List<InvoiceView> listForProject(Long projectId) {
49	        return jdbc.query(
50	                "SELECT id, project_id, amount, status, issued_date, due_date FROM invoices WHERE project_id = ? ORDER BY id ASC",
51	                (rs, i) -> new InvoiceView(rs.getLong("id"), rs.getLong("project_id"),
52	                        rs.getBigDecimal("amount"), rs.getString("status"),
53	                        rs.getDate("issued_date").toLocalDate().toString(),
54	                        rs.getDate("due_date").toLocalDate().toString()),
55	                projectId);
56	    }
57	
58	    @Transactional(readOnly = true)
59	    public List<InvoiceView> listForProjectByDueDate(Long projectId) {
60	        return jdbc.query(
61	                "SELECT id, project_id, amount, status, issued_date, due_date FROM invoices WHERE project_id = ? ORDER BY due_date ASC, id ASC",
62	                (rs, i) -> new InvoiceView(rs.getLong("id"), rs.getLong("project_id"),
63	                        rs.getBigDecimal("amount"), rs.getString("status"),
64	                        rs.getDate("issued_date").toLocalDate().toString(),
65	                        rs.getDate("due_date").toLocalDate().toString()),
66	                projectId);
67	    }
68	
69	    @Transactional
70	    public InvoiceView create(Long projectId, BigDecimal amount) {
71	        if (projectId == null) {
72	            throw new IllegalArgumentException("An invoice requires a project");
73	        }
74	        if (amount == null) {
75	            throw new IllegalArgumentException("An invoice requires an amount");
76	        }
77	        if (amount.signum() <= 0) {
78	            throw new IllegalArgumentException("An invoice amount must be greater than zero");
79	        }
80	        Invoice invoice = new Invoice();
81	        invoice.setProjectId(projectId);
82	        invoice.setAmount(amount);
83	        // A new invoice goes out today and is due 30 days later.
84	        LocalDate issued = LocalDate.now();
85	        invoice.setIssuedDate(issued);
86	        invoice.setDueDate(issued.plusDays(30));
87	        Invoice saved = repository.save(invoice);
88	        return new InvoiceView(saved.getId(), saved.getProjectId(), saved.getAmount(),
89	                saved.getStatus(), saved.getIssuedDate().toString(), saved.getDueDate().toString());
90	    }
91	
92	    @Transactional
93	    public InvoiceView send(Long invoiceId) {
94	        if (invoiceId == null) {
95	            throw new IllegalArgumentException("An invoice id is required");
96	        }
97	        InvoiceView current = find(invoiceId);
98	        if (!"DRAFT".equals(current.getStatus())) {
99	            throw new IllegalStateException("Only a draft invoice can be sent");
100	        }
101	        jdbc.update("UPDATE invoices SET status = 'SENT' WHERE id = ?", invoiceId);
102	        InvoiceView invoice = find(invoiceId);
103	        audit.record("INVOICE_SENT id=" + invoice.getId() + " amount="
104	                + invoice.getAmount().setScale(2));
105	        return invoice;
106	    }
107	
108	    @Transactional
109	    public InvoiceView pay(Long invoiceId) {
110	        if (invoiceId == null) {
111	            throw new IllegalArgumentException("An invoice id is required");
112	        }
113	        InvoiceView current = find(invoiceId);
114	        // Payment is only allowed once an invoice has been sent.
115	        if (!"SENT".equals(current.getStatus())) {
116	            throw new IllegalStateException("An invoice can only be paid once it has been sent");
117	        }
118	        jdbc.update("UPDATE invoices SET status = 'PAID' WHERE id = ?", invoiceId);
119	        InvoiceView invoice = find(invoiceId);
120	        audit.record("INVOICE_PAID id=" + invoice.getId() + " amount="
121	                + invoice.getAmount().setScale(2));
122	        return invoice;
123	    }
124	
125	    /** The line items of an invoice, in the order they were added. */
126	    @Transactional(readOnly = true)
127	    public List<LineItemView> listLineItems(Long invoiceId) {
128	        return jdbc.query(
129	                "SELECT id, invoice_id, description, qty, unit_price FROM line_items WHERE invoice_id = ? ORDER BY id ASC",
130	                (rs, i) -> new LineItemView(rs.getLong("id"), rs.getLong("invoice_id"),
131	                        rs.getString("description"), rs.getInt("qty"),
132	                        rs.getBigDecimal("unit_price")),
133	                invoiceId);
134	    }
135	
136	    /**
137	     * Add one line item to an invoice, then re-derive the invoice's amount as the sum of each line's
138	     * quantity times unit price so the stored total stays in step. Returns the invoice's line items.
139	     */
140	    @Transactional
141	    public List<LineItemView> addLineItem(Long invoiceId, NewLineItem body) {
142	        if (invoiceId == null) {
143	            throw new IllegalArgumentException("An invoice id is required");
144	        }
145	        if (body == null || body.getDescription() == null || body.getDescription().isBlank()) {
146	            throw new IllegalArgumentException("A line item requires a description");
147	        }
148	        if (body.getQty() == null || body.getQty() <= 0) {
149	            throw new IllegalArgumentException("A line item requires a quantity greater than zero");
150	        }
151	        if (body.getUnitPrice() == null || body.getUnitPrice().signum() < 0) {
152	            throw new IllegalArgumentException("A line item requires a unit price that is not negative");
153	        }
154	        LineItem lineItem = new LineItem();
155	        lineItem.setInvoiceId(invoiceId);
156	        lineItem.setDescription(body.getDescription());
157	        lineItem.setQty(body.getQty());
158	        lineItem.setUnitPrice(body.getUnitPrice());
159	        lineItemRepository.save(lineItem);
160	        jdbc.update(
161	                "UPDATE invoices SET amount = COALESCE((SELECT SUM(qty * unit_price) FROM line_items WHERE invoice_id = ?), 0) WHERE id = ?",
162	                invoiceId, invoiceId);
163	        return listLineItems(invoiceId);
164	    }
165	
166	    private InvoiceView find(Long invoiceId) {
167	        return jdbc.queryForObject(
168	                "SELECT id, project_id, amount, status, issued_date, due_date FROM invoices WHERE id = ?",
169	                (rs, i) -> new InvoiceView(rs.getLong("id"), rs.getLong("project_id"),
170	                        rs.getBigDecimal("amount"), rs.getString("status"),
171	                        rs.getDate("issued_date").toLocalDate().toString(),
172	                        rs.getDate("due_date").toLocalDate().toString()),
173	                invoiceId);
174	    }
175	}
176

